// Simple "Pixel Patrol" canvas game
// Canvas element with id="game" is assumed to exist in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas with id="game" not found');
  const ctx = canvas.getContext('2d');
  const width = canvas.width;
  const height = canvas.height;

  // Game state
  const ship = { w: 30, h: 10, x: width / 2 - 15, y: height - 20, speed: 4 };
  const bullets = [];
  const aliens = [];
  let score = 0;
  let damage = 0;
  const maxDamage = 3;
  let lastAlienSpawn = 0;
  const alienSpawnInterval = 2000; // ms
  const alienSpeed = 0.5;
  const bulletSpeed = 5;

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });

  function spawnAliens() {
    const cols = 8;
    const rows = 2;
    const alienW = 20;
    const alienH = 15;
    const padding = 5;
    const offsetX = (width - (cols * (alienW + padding))) / 2;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        aliens.push({
          x: offsetX + c * (alienW + padding),
          y: r * (alienH + padding),
          w: alienW,
          h: alienH,
        });
      }
    }
  }

  function update(dt) {
    // Ship movement
    if (keys['ArrowLeft'] && ship.x > 0) ship.x -= ship.speed;
    if (keys['ArrowRight'] && ship.x + ship.w < width) ship.x += ship.speed;
    // Shooting
    if (keys[' '] && !keys['_spacePressed']) {
      bullets.push({ x: ship.x + ship.w / 2, y: ship.y, w: 2, h: 8 });
      keys['_spacePressed'] = true;
    }
    if (!keys[' ']) keys['_spacePressed'] = false;

    // Update bullets
    for (let i = bullets.length - 1; i >= 0; i--) {
      const b = bullets[i];
      b.y -= bulletSpeed;
      if (b.y + b.h < 0) bullets.splice(i, 1);
    }

    // Spawn aliens periodically
    if (performance.now() - lastAlienSpawn > alienSpawnInterval) {
      spawnAliens();
      lastAlienSpawn = performance.now();
    }

    // Update aliens
    for (let i = aliens.length - 1; i >= 0; i--) {
      const a = aliens[i];
      a.y += alienSpeed;
      // Check if alien reached bottom
      if (a.y + a.h >= height) {
        aliens.splice(i, 1);
        damage++;
        if (damage >= maxDamage) {
          gameOver();
          return;
        }
      }
    }

    // Collision detection bullet‑alien
    for (let i = bullets.length - 1; i >= 0; i--) {
      const b = bullets[i];
      for (let j = aliens.length - 1; j >= 0; j--) {
        const a = aliens[j];
        if (
          b.x < a.x + a.w &&
          b.x + b.w > a.x &&
          b.y < a.y + a.h &&
          b.y + b.h > a.y
        ) {
          bullets.splice(i, 1);
          aliens.splice(j, 1);
          score++;
          break;
        }
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // Ship
    ctx.fillStyle = '#0f0';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // Bullets
    ctx.fillStyle = '#ff0';
    bullets.forEach(b => ctx.fillRect(b.x, b.y, b.w, b.h));
    // Aliens
    ctx.fillStyle = '#f00';
    aliens.forEach(a => ctx.fillRect(a.x, a.y, a.w, a.h));
    // UI
    ctx.fillStyle = '#fff';
    ctx.font = '12px sans-serif';
    ctx.fillText(`Score: ${score}`, 10, 15);
    ctx.fillText(`Damage: ${damage}/${maxDamage}`, 10, 30);
  }

  let lastTime = 0;
  function loop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    update(dt);
    draw();
    if (damage < maxDamage) requestAnimationFrame(loop);
  }

  function gameOver() {
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0, 0, width, height);
    ctx.fillStyle = '#fff';
    ctx.font = '20px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', width / 2, height / 2 - 10);
    ctx.fillText(`Score: ${score}`, width / 2, height / 2 + 20);
  }

  // Start loop
  requestAnimationFrame(loop);
})();
